describe('Form Submission in Modal Dialog', () => {
  beforeEach(() => {
    cy.visit('/form-modal');
  });

  it('should successfully submit form from modal and display success message', () => {
    // Open the modal by clicking the trigger button
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Fill in form fields
    cy.get('[data-testid="modal-form-name-input"]').type('John Doe');
    cy.get('[data-testid="modal-form-email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="modal-form-message-textarea"]').type('This is a test message');

    // Intercept the form submission API call
    cy.intercept('POST', '/api/form/submit').as('formSubmit');

    // Submit the form
    cy.get('[data-testid="modal-submit-button"]').click();

    // Wait for the API call
    cy.wait('@formSubmit');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');

    // Verify modal closes or shows confirmation
    cy.get('[data-testid="modal-dialog"]').should('be.visible');
    cy.get('[data-testid="close-modal-button"]').click();
    cy.get('[data-testid="modal-dialog"]').should('not.exist');
  });

  it('should display validation errors when submitting form with empty fields', () => {
    // Open the modal
    cy.get('[data-testid="open-modal-button"]').click();

    // Verify modal is visible
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Attempt to submit form without filling any fields
    cy.get('[data-testid="modal-submit-button"]').click();

    // Verify validation error messages appear
    cy.get('[data-testid="name-error-message"]').should('be.visible');
    cy.get('[data-testid="name-error-message"]').should('contain', 'Name is required');

    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="email-error-message"]').should('contain', 'Email is required');

    cy.get('[data-testid="message-error-message"]').should('be.visible');
    cy.get('[data-testid="message-error-message"]').should('contain', 'Message cannot be empty');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify form is still open
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Verify form fields still contain initial values (or are cleared if validation fails)
    cy.get('[data-testid="modal-form-name-input"]').should('have.value', '');
  });
});
